import java.io.PrintWriter

const val MOD = 998244353L
const val MAX = 500

val fac = LongArray(MAX + 1)
val finv = LongArray(MAX + 1)
val inv = LongArray(MAX + 1)

fun init() {
    fac[0] = 1
    fac[1] = 1
    finv[0] = 1
    finv[1] = 1
    inv[1] = 1
    for (i in 2..MAX) {
        fac[i] = fac[i - 1] * i % MOD
        inv[i] = MOD - inv[MOD.toInt() % i] * (MOD / i) % MOD
        finv[i] = finv[i - 1] * inv[i] % MOD
    }
}

fun modCombination(n: Int, k: Int): Long {
    if (n < k) return 0
    var nn = n
    var kk = k
    var ret = 1L
    while (nn > 0 || kk > 0) {
        val ni = nn % MOD.toInt()
        val ki = kk % MOD.toInt()
        ret = ret * fac[ni] % MOD * finv[ki] % MOD * finv[ni - ki] % MOD
        nn /= MOD.toInt()
        kk /= MOD.toInt()
    }
    return ret
}

